insert into public.missions (title, description, category, difficulty, points, verification_type, rules, starts_at, ends_at, cover_image, featured) values
  ('Foto con la bandera de España', 'Hazte una foto con la rojigualda: en tu balcón, en un acto, en el pueblo o donde ondee con más arte. Puntos extra de orgullo si es grande (los puntos de verdad son los de la misión).', 'españa', 'facil', 80, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-bandera/800/450', true),
  ('#España en X', 'Publica un post en X con el hashtag #España contando qué te gusta de tu tierra. Lo verificamos automáticamente.', 'redes', 'facil', 50, 'x_auto', '{"type":"post_with_hashtag","hashtag":"#España","min_count":1,"window_days":7}', null, null, 'https://picsum.photos/seed/fachapp-espana-x/800/450', false),
  ('Estrena el #FachApp', 'Publica un post en X con el hashtag #FachApp contando qué reto español vas a completar esta semana.', 'redes', 'facil', 50, 'x_auto', '{"type":"post_with_hashtag","hashtag":"#FachApp","min_count":1,"window_days":7}', null, null, 'https://picsum.photos/seed/fachapp-hashtag/800/450', false),
  ('#12deOctubre en X', 'Felicita la Fiesta Nacional en X con el hashtag #12deOctubre.', 'redes', 'facil', 60, 'x_auto', '{"type":"post_with_hashtag","hashtag":"#12deOctubre","min_count":1,"window_days":7}', '2026-10-05 00:00+02', '2026-10-19 23:59+02', 'https://picsum.photos/seed/fachapp-12-octubre-x/800/450', false),
  ('100 patriotas', 'Llega a 100 seguidores en tu cuenta de X.', 'redes', 'media', 150, 'x_auto', '{"type":"followers_min","value":100}', null, null, 'https://picsum.photos/seed/fachapp-comunidad/800/450', false),
  ('Embajador de España en X', 'Publica al menos 5 posts en X en los últimos 7 días hablando de lo nuestro.', 'redes', 'media', 100, 'x_auto', '{"type":"post_count","min":5,"window_days":7}', null, null, 'https://picsum.photos/seed/fachapp-activa/800/450', false),
  ('Selfie con alguien del PP', 'Hazte un selfie con un cargo o personaje conocido del Partido Popular: en un mitin, un acto público o por la calle. Siempre pidiendo permiso y con buen rollo.', 'actualidad', 'dificil', 200, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-selfie-pp/800/450', false),
  ('Desfile del 12 de Octubre', 'Fiesta Nacional: foto del desfile, de la Patrulla Águila pintando el cielo o de las banderas en los balcones de tu calle.', 'españa', 'media', 100, 'photo', '{}', '2026-10-10 00:00+02', '2026-10-13 23:59+02', 'https://picsum.photos/seed/fachapp-desfile/800/450', false),
  ('Día de la Constitución', 'El 6 de diciembre celebramos la Constitución de 1978. Foto con un ejemplar (o en un acto conmemorativo).', 'españa', 'facil', 60, 'photo', '{}', '2026-12-01 00:00+01', '2026-12-08 23:59+01', 'https://picsum.photos/seed/fachapp-constitucion/800/450', false),
  ('Con la camiseta de La Roja', 'Foto con la camiseta de la Selección. Si es la de algún Mundial o Eurocopa ganados, ya eres leyenda.', 'españa', 'facil', 60, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-la-roja/800/450', false),
  ('Atardecer en España', 'Haz una foto del atardecer desde tu rincón favorito de España.', 'naturaleza', 'facil', 80, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-atardecer/800/450', false),
  ('Amanecer en España', 'Madruga y fotografía un amanecer en cualquier punto de España. El café después te lo has ganado.', 'naturaleza', 'dificil', 120, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-amanecer/800/450', false),
  ('Monumento de tu provincia', 'Visita un monumento o lugar histórico de tu provincia y hazte una foto allí.', 'cultura', 'media', 100, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-monumento/800/450', false),
  ('Patrimonio de la Humanidad', 'España es de los países con más lugares Patrimonio de la Humanidad: la Alhambra, la Mezquita de Córdoba, la Sagrada Familia, Santiago… Foto en uno de ellos.', 'cultura', 'media', 120, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-patrimonio/800/450', false),
  ('Una etapa del Camino de Santiago', 'Haz una etapa del Camino (cualquiera vale) y sube una foto con la flecha amarilla o la concha. ¡Buen Camino!', 'cultura', 'dificil', 150, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-camino/800/450', false),
  ('El toro de Osborne', 'Busca uno de los toros de Osborne que vigilan nuestras carreteras y hazte una foto con él (sin ponerte en peligro en el arcén).', 'españa', 'media', 90, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-toro-osborne/800/450', false),
  ('Limpia una playa o un monte de España', 'Cuidar lo nuestro también es patriotismo: recoge basura en una playa, río o monte y sube una foto de lo que recogiste.', 'naturaleza', 'media', 150, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-limpieza/800/450', false),
  ('Tortilla: ¿con o sin cebolla?', 'El debate que divide España. Sube tu tortilla de patatas y declara tu bando con #ConCebolla o #SinCebolla. Las de bote no cuentan.', 'gastronomía', 'facil', 70, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-tortilla/800/450', false),
  ('Paella como Dios manda', 'Paella valenciana de verdad: sin chorizo y con socarrat. Si lleva chorizo, la comunidad votará en consecuencia.', 'gastronomía', 'media', 90, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-paella/800/450', false),
  ('Jamón, jamón', 'Foto de un buen plato de jamón ibérico (si lo cortas tú a cuchillo, mejor).', 'gastronomía', 'facil', 60, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-jamon/800/450', false),
  ('Las croquetas de la abuela', 'Foto de las mejores croquetas que conozcas. Si son de tu abuela, puntos extra de ternura.', 'gastronomía', 'facil', 60, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-croquetas/800/450', false),
  ('Tapeo con amigos', 'Sal de tapas con tus amigos y sube una foto de la mesa (sin caras si no quieren salir).', 'gastronomía', 'facil', 60, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-tapas/800/450', false),
  ('Oro líquido', 'España es la primera productora de aceite de oliva del mundo. Foto de tu AOVE español favorito o de una almazara.', 'gastronomía', 'media', 70, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-aceite/800/450', false),
  ('Fiestas de tu pueblo', 'Verbena, procesión, peñas o charanga: foto de las fiestas patronales de tu pueblo o barrio.', 'tradiciones', 'facil', 70, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-fiestas/800/450', false),
  ('Castañas asadas', 'Llega el otoño: cucurucho de castañas del puesto de la castañera. Foto antes de que se enfríen.', 'tradiciones', 'facil', 50, 'photo', '{}', null, '2026-12-15 23:59+01', 'https://picsum.photos/seed/fachapp-castanas/800/450', false),
  ('Huesos de santo y buñuelos', 'Todos los Santos se celebra comiendo. Foto de tus huesos de santo o buñuelos de viento.', 'tradiciones', 'facil', 60, 'photo', '{}', '2026-10-25 00:00+02', '2026-11-03 23:59+01', 'https://picsum.photos/seed/fachapp-bunuelos/800/450', false),
  ('El décimo de Navidad', 'Empieza la temporada de lotería. Foto de tu décimo (¡tapa los números de serie!) y comparte el número que te da buena espina.', 'tradiciones', 'facil', 50, 'photo', '{}', '2026-11-15 00:00+01', '2026-12-22 14:00+01', 'https://picsum.photos/seed/fachapp-loteria/800/450', false),
  ('Mascota rojigualda', 'Tu perro o tu gato con los colores de España: pañuelo, collar o lo que se deje poner (sin que sufra).', 'tradiciones', 'facil', 60, 'photo', '{}', null, null, 'https://picsum.photos/seed/fachapp-mascota/800/450', false),
  ('Frase de cuñado', 'Cuéntanos la frase más cuñada que hayas oído en la sobremesa ("esto en mi pueblo es gratis", "yo eso lo arreglo en un momento"…). Sin nombres: el cuñado es un concepto.', 'humor', 'facil', 40, 'manual', '{}', null, null, 'https://picsum.photos/seed/fachapp-cunado/800/450', false),
  ('Siesta de pijama y orinal', 'Patrimonio inmaterial: cuéntanos tu siesta épica (duración, lugar y si hubo babas). La comunidad decide si es digna.', 'humor', 'facil', 40, 'manual', '{}', null, null, 'https://picsum.photos/seed/fachapp-siesta/800/450', false),
  ('Una mañana por tu gente', 'Dedica una mañana a una ONG, banco de alimentos o parroquia de tu ciudad. Cuéntanos dónde fuiste y la comunidad lo validará.', 'solidaridad', 'dificil', 200, 'manual', '{}', null, null, 'https://picsum.photos/seed/fachapp-voluntariado/800/450', false);
